"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Meteora hoş geldin! Sen bir Konsorsiyum muharebe robotusun. Fareyle etrafına bak ve WASD ile yürü.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: Shift'e dokun — zıpla, Shift'i basılı tut — uç. Enerji yerde dolar.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Ateş — sol tık. Nişan — sağ tık: daha isabetli, yakınlaştırmalı. Birkaç el ateş et.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Doldurma — R. Mermiler en çok orta menzilde, 20–50 metrede vurur.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Roket — Q. Tanklara ve binalara karşı. Bir roket at.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Üstte stratejistin görevi var. Yeşil oklar boyunca koş: rotada sprint atarsın. Noktayı ele geçir — fenerin yanında dur.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Mangan seni kolluyor: portreleri ve canları solda. Geride kalırlarsa beklemeni isteyecekler.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — savaştan çıkmadan hızlı birim değiştirme: çatışmaya en yakın mangaya ya da tanka atla. Dene.",
"Next to a tank or turret press E to take control. Or just carry on.":"Tank ya da tareti yanındayken E'ye basıp kontrolü ele al. Ya da yoluna devam et.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Şimdi strateji. Sağ üstteki \"◩ Strateji\"ye dokun — savaş alanına kuşbakışı görünüm.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Şimdi strateji. {0} tuşuna bas (ya da sol üstteki \"◩ Strateji\"ye) — savaş alanına kuşbakışı görünüm.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Stratejide sana Rehber yardım eder: üstteki kutu ne yapacağını söyler, çerçeve düğmeyi gösterir, halka haritadaki yeri işaretler. Onun üç tavsiyesini yerine getir.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Bir manga seç ve yeşil \"▶ Ele Geçir\" düğmesine dokun — o askerin kontrolüyle yeniden savaşa dön. Sen ateş ederken YZ stratejisti orduyu yönetir.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Bir manga seç ve {0} tuşuna ya da yeşil \"▶ Ele Geçir\"e bas — o askerin kontrolüyle yeniden savaşa dön (seçim yoksa kendi robotuna). Sen ateş ederken YZ stratejisti orduyu yönetir.",
