"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Üstte YZ stratejisti'nin emri var. Onu yerine getir: ×2 ve ×3 XP, tamamlanan emirlere ödül de çıkabilir. Yeşil işaret ve oklar yolu gösterir.",
