"Targets are far — the railgun is stronger at long range.":"Hedefler uzakta — uzun menzilde railgun daha güçlü.",
"You have a temporary heavy MG — use it before it is recalled.":"Elinde geçici ağır makineli tüfek var — geri alınmadan önce kullan.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkur: koşarken C — kayma, çıkıntıya zıpla — tırman, havadayken duvarın yanında zıpla — duvar zıplaması.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Mermiler en çok 20–50 m'de vurur. Yakın ve uzak menzilde çok daha zayıftır — düşmanlar için de.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Robotun ağır hasarlı. Ateşin altından çık — çatışma dışında zırh kendini onarır.",
"One of our tanks is close. Walk up and press E to take control.":"Yakınlarda bir tankımız var. Yaklaş ve E'ye basıp kontrolü ele al.",
"Man the turret — press E next to it.":"Tareti kullan — yanındayken E'ye bas.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Burası sakin. Çatışmaya daha yakın bir manga ya da araca geç.",
"Reload early while no enemies are around.":"Çevrede düşman yokken şarjörünü erkenden doldur.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Stratejistin yeşil oklarını izleyerek koş — onun rotasında daha hızlı koşarsın.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"\"◩ Strateji\" düğmesi — kuşbakışı görünüm: üs kur, asker sipariş et, mangalara komut ver.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Strateji modu: üs kur, asker sipariş et, saldırı çağır ve mangalara komut ver. Orada aynı tuş, seçili birimi ele geçirir.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Komutayı kendin mi istiyorsun? YZ stratejisti'ni kapat — emirleri sen verirsin.",
"Third-person view — to see your robot.":"Üçüncü kişi görünümü — robotunu görmek için.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tank: {0} — nişan noktasına yaylım, {1} — duman perdesi, {2} — aşırı yükleme. {3} — piyadeye dön.",
"Plenty of targets — fire a barrage.":"Çok hedef var — yaylım ateşi aç.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — yukarı/aşağı, sol tık — ateş, {2} — nişan noktasına çarp.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Bir manga seç — sol tık, çerçeve ya da soldaki kart. Yere sağ tık — saldırarak ilerle ⚔, düşmana — saldırı, noktaya — ele geçirme.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Mangaların yetenekleri var: el bombaları, jetpack atılımı, bastırma, onarım. Tanklarda: yaylım, duman, aşırı yükleme.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Bol cevher var — Karargâh'ı ya da bir fabrikayı seç ve sağdaki panelden asker sipariş et.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Komuta puanları birikiyor — \"Güçler\" sekmesi: keşif, topçu ateşi, manga iniş kapsülü, yörünge saldırısı.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Binaları yalnızca mühendisler inşa eder: bir mühendis seç (İnşa sekmesindeki düğme ya da bina tuşu), sonra yere tıkla. Parlayan damar üzerine Ekstraktör (C) — daha fazla cevher.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Sol üstteki \"CEVHER\"e tıkla — cevher nereden gelir ve gelir nasıl artar.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — grubu kaydet, 1…9 — grubu seç, çift basış — kamera gruba gider.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Bir birim seç ve aşağıdaki yeşil \"▶ Ele Geçir\"e dokun (ya da çift dokun) — kendin savaşırsın. \"◩ Strateji\" seni geri getirir.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Bir birim seç ve aşağıdaki yeşil \"▶ Ele Geçir\"e ya da {0} tuşuna bas (ya da çift tıkla) — kendin savaşırsın. Savaşta {1} seni stratejiye döndürür.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Gri düğmelere de basabilirsin: neyin eksik olduğunu, ne kadar bekleneceğini ve nasıl düzeltileceğini gösteririz.",
"RMB on the ground — rally point for this building's new troops.":"Yere sağ tık — bu binanın yeni askerleri için toplanma noktası.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Sağ tık — saldırarak ilerle ⚔: düşmanla karşılaşınca durup savaşırlar, sonra yollarına devam eder. Çift sağ tık — yürüyüş »: durmadan koşarlar, giderken ateş ederler. Bekle/Geri çekil — \"Diğer emirler ▾\".",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: parmakla sürükle, iki parmakla — yakınlaştır ve döndür, mini haritayı da parmakla sürükleyebilirsin.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD ve ekran kenarları, Q/E döndürür, tekerlek yakınlaştırır (imlece doğru), orta tuş yörünge, mini harita — tıkla ya da sürükle, Boşluk — son uyarıya git.",
