"New in v6.2":"v6.2'de yeni",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Yeni cevher görünümü: damarlar kara bazalt üzerinde kıvılcımlı, yeşil sisli, parlayan zümrüt kesim kristaller; çıkarıcı — altıgen kaide, petek kubbe ve tepesinde yeşil fener olan kafes kule (şerit ve flama takım renginde)",
"New in v6.1":"v6.1'de yeni",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield'daki gibi tercih edilen sınıf (U, ölümden sonra rakam tuşları): uygunsa o sınıfta yeniden doğarsın",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Araçlar birinci şahıs görünümünde (V — dışarıdan/kabinden); hafif nişan yardımı — Ayarlar'da",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Çekirdekten çıkmak kolaylaştı: Boşluk — şafta, B — yüzeye kapsül; ölünce yetenek etkileri sıfırlanır",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Sonsuz gelişim: generaller ve Mareşal ★, kariyer seviyeleri, silah ustalığı ve ekipmanlar, madalyalar, günlük sözleşmeler — Kariyer ekranı",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strateji: tekerlekle yumuşak zum, birimlerin üstünde simgeler ve etiketler (Alt — hepsi), solda Birlikler / Yapılar paneli",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"sağ tık — saldırarak ilerle, çift sağ tık — hareket halinde ateş ederek yürüyüş; nadir emirler \"Diğer emirler ▾\" içinde; tekrar eden düğme yok",
"New in v6":"v6 yenilikleri",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Nişancı oyunlarındaki gibi atış: anlık mermiler, dakikada 720 atışlı tüfek, makineli tüfek, geri tepme, sağ tıkla nişan, şarjörler ve R ile doldurma, isabet işaretleri",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Daha ağır yerçekimi, tepkili jetpack, Z ile veya havada çift jetpack ile atılma; başka birime geçerken silah artık peşinden uçmuyor",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Mühendisler: bir mühendis seç, yapıyı seç, planı yerleştir; cevher damarlarına çıkarıcılar; \"CEVHER\"e tıkla — gelirin kaynağı ve nasıl hızlanacağı",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Gri düğmeler nedenini açıklar ve çözüm sunar; büyük düğmeler, \"Sürüyor\" şeridi, \"▶ Ele Geçir\", Tab tek mod tuşu",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Sıçramasız ve takla atmayan strateji kamerası, imlece doğru zum, sürüklenebilir mini harita",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Yeni araçlar: \"Jackal\" akıncı, \"Grad\" çok namlulu roketatar (güdümlü roketler), \"Hammer\" havan; Swarm \"Wasp\", \"Hive\", \"Trebuchet\" kazandı",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Stratejist emirleri değiştirip durmaz, sesli spam yapmaz; çatışmalar yanına gelir; B — yeniden konuşlan, Shift+B — savaşın ortasına; pusula, H — hangi hedef",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Serbest oyun (K) ve tek başına hareket (J), F2 hazır ayarlar; Esc duraklatır ve devam ettirir; kayıtlar: slotlar, dosya dışa ve içe aktarma",
"New in v5.3":"v5.3 yenilikleri",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Uçuş: meteordan uzakta yerçekimi daha güçlü, havada C ile fren yapılır, itiş daha keskin yönlendirir; artık portalda takılıp kalmazsın",
"New in v5":"v5 yenilikleri",
