"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"El bombaları: G'yi basılı tut — uçuş yayı, patlama noktası ve yarıçapı, mesafe görünür; bırak — at. Menzil bakış açısıyla, tekerlek — güç, sağ tık — alttan atış",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"El bombası zıplar ve yokuştan yuvarlanır, 2.5 sn sonra patlar; 2 el bombası, 9 sn'de yenilenir; yakındaki düşman el bombası için uyarı simgesi",
