"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"El bombası ({0}): basılı tut — uçuş yayı, patlama noktası ve dairesi, mesafe; bırak — at; kısa basış hemen atar. Menzil bakış açısıyla, tekerlek — güç, sağ tık — alttan atış. Telefon: G'yi basılı tut ve parmağını sürükle.",
