"HQ: {0} ready":"Karargâh: {0} hazır",
"HQ: {0} online":"Karargâh: {0} hizmette",
"Intel: the Swarm HQ got \"{0}\"":"Keşif: Sürü karargâhı \"{0}\" aldı",
"Point {0}: orbit is dropping a pod — a squad{1}":"{0} noktası: yörünge bir kapsül bırakıyor — manga{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"{0} noktasındaki kapsül: {1}{2}{3}. Mühendis ileri karakol kurabilir (V) ve bir geliştirme dalı seçebilir.",
"HQ radar: every enemy is visible for 6 s":"Karargâh radarı: tüm düşmanlar 6 sn görünür",
"HQ upgrades":"Karargâh geliştirmeleri",
"Built":"İnşa edildi",
"Building — click to cancel (refund)":"İnşa ediliyor — tıkla: iptal et (cevher iade edilir)",
"Outpost upgrades":"İleri karakol geliştirmeleri",
"point":"nokta",
"Pick a branch — every point gets its own speciality:":"Bir dal seç — her noktanın kendi uzmanlığı var:",
"Building — click to cancel":"İnşa ediliyor — tıkla: iptal et",
"A builder near the outpost (30 m) does the upgrade.":"Geliştirmeyi ileri karakolun yanındaki (30 m) mühendis yapar.",
"Send a builder":"Mühendis gönder",
"Builders nearby":"Yakındaki mühendisler",
"{0} is heading to the outpost":"{0} ileri karakola gidiyor",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Savaşın en başından itibaren karargâhta tüm ordu birer tane duruyor: paraşütçü, tekil ağır silahçı, keskin nişancı, gözcü, dron, akıncı, çok namlulu roketatar, havan (ve hücum mangaları ile tank) — hemen istediğine Ele Geçir",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"Ele geçirme için \"Kendi sıram\" (duraklatma menüsü, telefonda ☰): her sınıfın bir numarası var, 1 en önemlisi; ▲▼ değiştirir, ✕ hiç demek. Ölümden sonra ve X'te bu sıraya göre çatışmaya en yakın asker alınır",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Botlar artık keskin nişancı değil: uzaktan, koşarken, koşanlara ve siperdekilere karşı ıskalarlar; kurşunlar yanından vınlar, toprağa ve yakındaki siperlere çarpar. Patlamalar seni yere serer: sarsılma, diz çökme, ayaktan düşme ve tekrar kalkma",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Bir noktayı ele geçir, kapsülle manga ve mühendis iner. Noktadaki ileri karakol tek bir daldan gelişir: savunma (makineli bunker → tanksavar toplu ağır bunker), destek (tamir dronları → güç alanı kubbesi), keşif (telsiz tarayıcı → keskin nişancı kulesi)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Karargâh da gelişir: zırh plakaları, taretler, hızlı yörünge indirmesi, gelir +%25, küresel radar, iletişim antenleri (+komuta puanı). YZ de aynısını yapar",
"New in v7.0":"v7.0'da yenilikler",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"Karargâhta her türden birer asker ve araç var: paraşütçü, keskin nişancı, gözcü, dron, akıncı, çok namlulu roketatar, havan. İstediğini seç ve {0} — daha inşa etmeden dene.",
"POSSESS":"ELE GEÇİR",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"{0} noktası: kapsülle bir mühendis indi. Onu seç ve noktanın yanına bir \"İleri karakol\"{1} kur — sonra geliştirme dalını seçersin.",
"OUTPOST":"İLERİ KARAKOL",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"İleri karakol hazır — seç ve bir dal belirle: ⛨ Savunma (makineli bunker, tanksavar bunker), ✚ Destek (tamir dronları, güç alanı kubbesi) veya ◎ Keşif (tarayıcı, keskin nişancı kulesi). Yakındaki bir mühendis inşa eder.",
"UPGRADE":"GELİŞTİR",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Karargâh bir \"süper nokta\": onu seç{0} — zırh plakaları, taretler, hızlı indirme, gelir +%25, radar, iletişim antenleri.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → \"Ele Geçirme\": \"Kendi sıram\"ı aç ve ölümden sonra kimi alacağını seç — 1, 2… ✕ hiç demek.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → duraklat → \"Kendi sıram\": ölümden sonra ve X'te kimi alacağını seç — 1, 2… ✕ hiç demek.",
