"Phone: new shooter controls — stick, Fire and Jet on the left, look by swipe or a second stick on the right; AUTO locks on with a red frame like Syphon Filter: your trooper keeps the target and fires, the stick circles around it, a swipe flicks to the next target":"Telefon: yeni nişancı kontrolü — solda çubuk, \"Ateş\" ve \"Jetpack\", sağda kaydırarak veya ikinci çubukla görüş; \"OTO\" Syphon Filter gibi kırmızı çerçeveyle hedef kilitler: askerin hedefi tutup kendi ateş eder, çubukla etrafında dönersin, kaydırarak yan hedefe geçersin",
"Gestures: double tap on the right — reflex; tap the red frame — rocket, swipe \"Grenade\" up — a grenade right at the target (or variant B — pinch); first-run gesture hints, icons instead of words, skills and \"hide HUD\" at the top":"Hareketler: sağa çift dokun — refleks; kırmızı çerçeveye dokun — roket, \"El bombası\"nı yukarı kaydır — bomba tam hedefe (ya da B seçeneği — sıkıştır); ilk açılışta hareket ipuçları, kelime yerine simgeler, üstte yetenekler ve \"HUD'u gizle\"",
"Strategy on the phone: tap to select and order, hold for a radial menu (attack, hold, patrol, build, rally), hold and drag for a box, double tap for all of a type on screen; infantry / vehicles / drones / builders buttons, squad cards 1-2-3, follow camera, haptic ticks":"Telefonda strateji: dokun — seç ve emret, basılı tut — dairesel menü (saldır, bekle, devriye, inşa et, toplan), basılı tutup sürükle — çerçeve, çift dokun — ekrandaki aynı türün hepsi; \"piyade / araçlar / dronlar / mühendisler\" düğmeleri, manga kartları 1-2-3, \"takip\", titreşim geri bildirimi",
"Phone menus without sliders or scrolling: every section is its own screen with big buttons, languages as flags, \"− value +\", \"Back / ✕ / Apply\"":"Telefon menüleri kaydırıcısız ve kaydırmasız: her bölüm ayrı ekran, büyük düğmeler, diller bayraklarla, \"− değer +\", \"Geri / ✕ / Uygula\"",
"Developer mode: \"Polygon\" in the Arsenal — an endless battle of every squad type and vehicle at the map centre with reinforcements for both sides; X takes you straight into a soldier there (PC and phone)":"Geliştirici modu: Cephanelikte \"Poligon\" — haritanın ortasında her türden mangaların ve tüm araçların sonsuz savaşı, iki tarafa takviye; X seni doğrudan oradaki bir askere geçirir (PC ve telefon)",
"PC":"PC",
"Move the mouse to turn your view.":"Fareyi oynat — bakışın döner.",
