"Hold {0} — the jetpack lifts you up.":"{0} basılı tut — jetpack seni havaya kaldırır.",
"Take off ({0}) and press {1} in the air — brake.":"Havalan ({0}) ve havada {1} tuşuna bas — fren.",
"Aim at a dummy and press LMB.":"Bir mankene nişan al ve sol tık.",
"Hold RMB — aim with zoom.":"Sağ tık basılı tut — yakınlaştırmalı nişan.",
"Press {0}.":"{0} tuşuna bas.",
"Aim at a dummy and press {0}.":"Bir mankene nişan al ve {0} tuşuna bas.",
"Press {0} to throw (hold longer — farther).":"Atmak için {0} tuşuna bas (daha uzun tut — daha uzağa).",
"Get behind the wall until the sniper marker turns grey.":"Keskin nişancı işareti griye dönene kadar duvarın arkasına geç.",
"Press {0} — \"squad with me ⇄ going solo\".":"{0} tuşuna bas — \"manga benimle ⇄ tek başıma\".",
"Press {0} or \"◩ Strategy\" at the top left.":"{0} tuşuna bas ya da sol üstteki \"◩ Strateji\"ye dokun.",
"Press {0} or the green \"▶ Possess\" below.":"{0} tuşuna bas ya da aşağıdaki yeşil \"▶ Ele Geçir\"e dokun.",
"W A S D or arrows move the camera (or push the mouse to the screen edge).":"W A S D veya oklar kamerayı kaydırır (ya da fareyi ekran kenarına götür).",
"Scroll the mouse wheel.":"Fare tekerleğini çevir.",
"LMB on the squad with the green marker.":"Yeşil işaretli mangaya sol tık.",
"RMB on the yellow marker on the ground (double RMB — run).":"Yerdeki sarı işarete sağ tık (çift sağ tık — koşarak).",
"Ctrl + LMB on a squad — all of that type on screen get selected.":"Ctrl + mangaya sol tık — ekrandaki bu türün hepsi seçilir.",
"Hold LMB on empty ground and drag a box over the squads.":"Boş zemine sol tıkı basılı tut ve mangaların üzerine çerçeve sürükle.",
"LMB on the minimap at the bottom left — the camera jumps there.":"Sol alttaki mini haritaya sol tık — kamera oraya atlar.",
"LMB on the marked builder (or \".\" — nearest builder).":"İşaretli mühendise sol tık (ya da \".\" — en yakın mühendis).",
"\"Barracks\" on the right ({0}), then LMB on the ground at the marker.":"Sağda \"Kışla\" ({0}), sonra işaretin yanındaki zemine sol tık.",
"No input needed — watch the building rise.":"Bir şey basmana gerek yok — yapının yükselişini izle.",
"LMB on the Barracks → \"Assault squad\" on the right.":"Kışla'ya sol tık → sağda \"Taarruz mangası\".",
"Select a builder and RMB on the green crystals.":"Bir mühendis seç ve yeşil kristallere sağ tık.",
"Drag a finger on the right half of the screen.":"Ekranın sağ yarısında parmağını sürükle.",
"Touch the left side and slide — that is the stick. Reach the green marker.":"Sol tarafa dokun ve parmağını kaydır — bu çubuk. Yeşil işarete ulaş.",
"Hold the \"Jet\" button.":"\"Jetpack\" düğmesini basılı tut.",
"Aim at a dummy with your right finger and hold \"Fire\".":"Sağ parmağınla bir mankene nişan al ve \"Ateş\"i basılı tut.",
"Tap \"Reload\".":"\"Şarjör\"e dokun.",
"Tap \"AUTO\" — a red frame locks the dummy and your trooper fires.":"\"OTO\"ya dokun — kırmızı çerçeve mankeni kilitler, askerin kendi ateş eder.",
"Tap the red frame on the target — a rocket flies. (No frame? Turn on \"AUTO\".)":"Hedefteki kırmızı çerçeveye dokun — roket çıkar. (Çerçeve yok mu? \"OTO\"yu aç.)",
"Rocket fired from the skills row. Try tapping the red frame itself.":"Roket yetenek sırasından çıktı. Doğrudan kırmızı çerçeveye dokunmayı dene.",
"Swipe up on \"Grenade\" — it flies right at the target.":"\"El bombası\"nı yukarı kaydır — bomba tam hedefe uçar.",
"That was a normal throw. Now swipe up on the button — at the target.":"Bu normal bir atıştı. Şimdi düğmeyi yukarı kaydır — hedefe.",
"Double tap quickly on the right half of the screen.":"Ekranın sağ yarısına hızlıca iki kez dokun.",
"Tap the lightning bolt at the top right — the skills row opens.":"Sağ üstteki şimşeğe dokun — yetenek sırası açılır.",
"Use the stick to get behind the wall until the sniper marker turns grey.":"Çubukla, keskin nişancı işareti griye dönene kadar duvarın arkasına geç.",
"Tap \"⇆\" at the top right.":"Sağ üstteki \"⇆\"ye dokun.",
"Tap the \"Squad with me\" tag at the top left.":"Sol üstteki \"Manga benimle\" etiketine dokun.",
"Tap \"◩ Strategy\" at the top right.":"Sağ üstteki \"◩ Strateji\"ye dokun.",
"Tap \"▶ To battle\" at the top right (or \"Possess\" on the card).":"Sağ üstteki \"▶ Savaşa\"ya dokun (ya da kartta \"Ele Geçir\").",
"Drag one finger across the map.":"Bir parmakla haritada sürükle.",
"Pinch with two fingers — closer / farther.":"İki parmakla sıkıştır — yakın / uzak.",
"Tap the squad with the green marker.":"Yeşil işaretli mangaya dokun.",
"Tap the yellow marker on the ground (double tap — run).":"Yerdeki sarı işarete dokun (çift dokun — koşarak).",
"Double tap a squad — all of that type on screen get selected.":"Mangaya çift dokun — ekrandaki bu türün hepsi seçilir.",
"Hold a finger on empty ground until the yellow ring, then drag — a box appears.":"Boş zeminde sarı halka çıkana dek parmağını tut, sonra sürükle — çerçeve oluşur.",
"Hold a finger on the ground at the marker until the ring, then release — a radial menu opens.":"İşaretin yanında yerde halka çıkana dek parmağını tut ve bırak — dairesel menü açılır.",
"Tap card \"2\" on the left (double tap — camera to the squad).":"Soldaki \"2\" kartına dokun (çift dokun — kamera mangaya).",
"Tap the minimap at the bottom left — the camera jumps there.":"Sol alttaki mini haritaya dokun — kamera oraya atlar.",
"Tap \"Builders\" on the right or the marked builder.":"Sağdaki \"Mühendisler\"e ya da işaretli mühendise dokun.",
"\"Barracks\" on the right → tap the ground at the marker → \"✔ Build\".":"Sağda \"Kışla\" → işaretin yanındaki zemine dokun → \"✔ İnşa et\".",
"Tap the Barracks → \"Assault squad\" on the right.":"Kışla'ya dokun → sağda \"Taarruz mangası\".",
"Select a builder and tap the green crystals.":"Bir mühendis seç ve yeşil kristallere dokun.",
"Tap the green \"▶ Possess\" on the card (or hold on a squad → \"Possess\").":"Kartta yeşil \"▶ Ele Geçir\"e dokun (ya da mangaya basılı tut → \"Ele Geçir\").",
