"training complete":"eğitim tamamlandı",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Yakınlaştırmak için \"Nişan\"a dokun. Tekrar dokun — geri.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Manga seni takip ediyor. ☰ → \"Duraklat\" → \"Manga benimle\" karesini aç — \"Tek başıma\" olur.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Mühendis seçildi — aşağıdaki kartında \"◆ Kristal topla\"ya dokun (ya da yeşil kristallere dokun).",
"Training complete!":"Eğitim tamamlandı!",
"steps":"adım",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Üs kurmayı, birlik sipariş etmeyi, komuta etmeyi ve savaşa atlamayı biliyorsun. Sırada gerçek bir maç var: Rehber oyun sırasında yardım edecek.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Hareket etmeyi, uçmayı, ateş etmeyi, siper almayı ve mangayı komuta etmeyi biliyorsun. Sırada gerçek bir maç var.",
"Real battle":"Gerçek savaş",
"Again":"Tekrar",
"done":"tamamlandı",
"you are on PC: keyboard and mouse":"PC kullanıyorsun: klavye ve mouse",
"you are on a phone: touch screen":"telefon kullanıyorsun: dokunmatik ekran",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Güvenli kum havuzu: düşmanlar hareketsiz mankenler, kimse sana ateş etmez. Bir adım, yalnızca eylemi gerçekten yaptığında sayılır.",
"Show others (training for the other device)":"Diğerlerini göster (diğer cihaz için eğitimler)",
"Old training (v7.1)":"Eski eğitim (v7.1)",
"Back to the normal device mode":"Normal cihaz moduna dön",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Diğer cihaz için eğitim, sayfayı o cihazın modunda yeniden başlatır (PC — fare ve klavye, telefon — dokunmatik; PC'de dokunmatiği Chrome'da test edebilirsin: F12 → telefon simgesi).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Eğitim ×4: PC ve telefon için ayrı, adım adım \"Strateji\" ve \"Nişancı\" dersleri. Mankenli güvenli bir deneme alanı, vurgulanan doğru düğme, oklar, animasyonlu tuşlar, fare ve hareketler; adım yalnızca gerçek eylemle sayılır, \"adımı tekrarla\", üstte ilerleme ve sonunda ödül",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Eğitim menüsü cihazına uygun dersleri gösterir; \"Diğerlerini göster\" — dört dersin hepsini her cihazda açar; \"Eski eğitim (v7.1)\" de yerinde duruyor",
"New in v7.2":"v7.2'de yenilikler",
"NEW IN v7.2":"v7.2'DE YENİLİKLER",
"No grenades left":"El bombası kalmadı",
"Rocket and grenade recharging · {0} s":"Roket ve el bombası doluyor · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Solda — yürü, sağda — bak · düşmana dokun — roket / el bombası · 2 dokunuş — refleks · 3 dokunuş — topçu ateşi",
"Less":"Daha az",
"More":"Daha çok",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Yakında düşman aracı veya yapısı var — ona dokun: roket gider.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Çok düşman var — sağda boş bir yere hızlıca 2 kez dokun: refleks zamanı yavaşlatır.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Nişangâhı düşman kümesine getir ve 3 kez dokun — topçu ateşi.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Sol parmak — yürü, sağ parmak — bak. Nişan düşmandayken ateş kendiliğinden açılır.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"Sol kenardaki ⇑ — jetpack: zıplamak için dokun, uçmak için basılı tut.",
"Old v7.2 layout":"Eski v7.2 düzeni",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Ekranın sağ yarısında parmağını kaydır — parmağının altında bakış çubuğu belirir.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Sol tarafa dokunup parmağını kaydır — parmağının altında çubuk belirir. Yeşil işarete ulaş.",
"Hold the \"Jet\" button at the left edge.":"Sol kenardaki \"Jetpack\" düğmesini basılı tut.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Sağ çubukla mankene nişan al — nişangâh üzerindeyken askerin kendiliğinden ateş eder.",
"Tap the dummy on the screen — a rocket flies.":"Ekrandaki mankene dokun — roket fırlar.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Mankene dokun — el bombası tam hedefe doğru kavisle uçar.",
"Double tap an empty spot on the right quickly.":"Sağda boş bir yere hızlıca 2 kez dokun.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Zayıf telefonlar için hafif mod: düşük çözünürlük, gölge ve bozulma yok, yarı sayıda bot ve parçacık, 30 FPS sınırı; FPS < 25 olursa çözünürlüğü kendisi düşürür. Telefonlarda varsayılan olarak açık (Ayarlar → Grafikler → \"Hafif mod\"; ya da bağlantıda ?lite=1 / ?lite=0).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: yeni kontroller. Solda — yürü, sağda — bak (iki çubuk da parmağının altında belirir). Yalnızca sol parmak — \"oto\"; sağ parmak da devredeyken asker yalnızca nişangâh düşmandayken kendiliğinden ateş eder. Düşmana dokun — roket veya el bombası, 2 dokunuş — refleks, 3 dokunuş — topçu ateşi. Otomatik şarjör değişimi. Jetpack — sol kenarda düğme. Alt köşeler boş, mini harita köşede, ipuçları çarpıyla kapatılır, görev daraltılabilir. Eski düzen: Ayarlar → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"İpuçları (açılır pencereler ve rehber) — ayarlarda tek anahtar. Kim olarak oynadığın (asker veya araç türü) — HUD'da \"Sen: …\" yazısı. Tüfek ve makineli tüfek nişangâhları şeffaf. \"Cephanelik\" paneli sağa yaslı, daraltılabilir ve kapatılabilir. \"Manga olmadan tek başına\" (J) kaldırıldı. Stratejist sesi artık aynı sözü üst üste tekrarlamıyor. Tanklarda taret–gövde göstergesi var. Strateji eğitiminin başında imleç artık kaybolmuyor.",
