"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Silahın başında: {0}. Aracı YZ sürer, sen ateş edersin. {1} — in",
"The vehicle is destroyed — you jumped off":"Araç vuruldu — dışarı atladın",
