"Combo ×{0} · reflex +{1}%":"Kombo ×{0} · refleks +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"Stratejist: sana asker indiriliyor — +{0} (−{1} cevher)",
