"Advanced: class order":"Gelişmiş: sınıf sırası",
"Voice of hints and curator":"İpuçları ve rehber sesi",
"Advanced: custom class order":"Gelişmiş: özel sınıf sırası",
"Voice of hints & curator":"İpuçları ve rehber sesi",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: üç joystick modu. Yalnızca sol — \"oto\" (güçlü mıknatıs, zayıf mermi). Yalnızca sağ — nişan kendiliğinden açılır, mıknatıs daha güçlü, atış daha isabetli. İkisi birden — nişan yok, mıknatıs ve isabet daha zayıf. Sağdaki 👁 düğmesi arayüzü gizler/geri getirir.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strateji basitleştirildi — yalnızca mühendis ve yapılar. Solda kartlar (mühendis, karargâh, kışla…): dokun — kamera oraya uçar, altta hemen ne inşa/üretileceği çıkar. \"Savaşa\" — sol üstte. Ordu kendi başına savaşır. Tam strateji — Ayarlar → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Ele geçirme — iki onay kutusu: \"Mangalar\" ve \"Araçlar\" (telefonda araçlar varsayılan olarak kapalı — onları YZ sürer). Araçlar kapalıyken dost bir aracın yanında E (telefonda — sağdaki düğme) — silahının başına geç: araç kendisi gider, sen ateş edersin. Eski \"özel sınıf sırası\" — \"Gelişmiş\" altında. Ele geçirdiğinde birim telsizden yanıt verir.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Akıllı ipuçları: temel ipuçları 2. açılıştan sonra kendiliğinden kapanır, ama oyun hiç kullanmadığın bir özelliği yine de hatırlatır. Onay kutuları: temel / gelişmiş / nadir, ayrıca ipuçları ve rehber sesi için ayrı bir tane.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks öldürmelerle dolar (seri daha çok doldurur). Takım arkadaşların geride kaldı veya öldü — stratejist sana yenilerini indirir (normal takviyeden pahalı). v7.2gfx grafikleri ve sesi eklendi: kabaran patlamalar, duman, enkaz, kuyu ve krater akustiği. Derleme tarihi artık gerçek.",
"New in v7.4":"v7.4'te yenilikler",
"NEW IN v7.4":"v7.4'TE YENİLİKLER",
