"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Kariyer ve kayıtlar değişmeden kalır. Savaşta aynı menü, sağ üstteki \"🛠 Menü\" düğmesidir{0}.",
"New developer match":"Yeni geliştirici maçı",
"all unlocked, endless ore, instant build, arsenal":"her şey açık, sınırsız cevher, anında inşaat, cephanelik",
"Trainings — all 4":"Eğitimler — hepsi 4",
"PC and phone (strategy and shooter)":"PC ve telefon (strateji ve nişancı)",
"Cinema: split screen":"Sinema: bölünmüş ekran",
"strategist bot left, shooter bot right":"solda stratejist bot, sağda nişancı bot",
"Cinema: everything built":"Sinema: her şey inşa edildi",
"both bases built and upgraded — for footage":"iki üs de inşa edildi ve geliştirildi — çekim için",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Sinema modu — bölünmüş ekran: solda stratejist bot (üs ve orduya yukarıdan görünüm), sağda birinci şahıs nişancı bot. Altta düğmeler (ve S, P tuşları): \"Bölünmüş ekran\" ve \"★ Hepsi inşa edildi\" — çekim için iki üs de inşa edilip geliştirilir.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Çekirdek ve meteoru boydan boya geçen tüneller artık yok — meteor tek parça, savaş sadece yüzeyde.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 arayüzü gizler ama jetpack'i, ⇆'yi, çubukları ve görev işaretini bırakır. \"◎ Nişan\" (yalnızca sağ parmak) — belirgin biçimde daha güçlü ve geniş mıknatıs; üç mod için mıknatıs gücü — Ayarlar → Kontroller → \"Gelişmiş\". Araç topunda düğmenin adı \"İn\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Eğitim: telefonda yalnızca telefon eğitimleri, PC'de yalnızca PC eğitimleri. 4'ü de \"🛠 Geliştirici\" menüsünde. Geliştirici modu ve Cephanelik artık tek menüde (savaşta — sağ üstte \"🛠 Menü\", PC'de F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"\"Dendy (8-bit)\" ve \"16-bit\" grafik stilleri: Ayarlar → Grafikler → \"Grafik stili\" (ayrıntılar — ⚙ düğmesi). Maçın ilk ~10 sn'sinde FPS 24'ün altındaysa Dendy kendiliğinden açılır (20'nin altında — daha büyük piksel, 120 satır); \"normale dön\" bildirimi normal grafiği kalıcı olarak geri getirir. Menüdeki kendi seçimin her zaman önceliklidir.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D çevre modelleri (harabeler, enkazlar, tahkimatlar) — yalnızca iyi puan alanlar, talep üzerine yüklenir. Kapatmak için: Ayarlar → Grafikler → \"Yeni 3D çevre modelleri\".",
