"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Askerler inşa edebilir: kendi inşaat alanında E (telefonda \"Gir\") — askerin kendisi inşa eder, yakındaki manga arkadaşları yardım eder. Mühendisler meşgulse stratejist senden yardım ister — \"İNŞAAT ALANI\" işareti.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Stratejist işaretleri: stratejist yakınındaki düşman kümesine ⌖ koyar — 8 sn sonra topçu ateşi oraya düşer ve yakındaki dost \"Grad\"lar salvo yapar. Strateji modundan kendi topçu ateşin de \"Grad\" desteği alır.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Kargo konteynerlerinde ve düşmüş uydularda silah depoları (📦 70 m'den görünür): E — 90 sn ağır makineli tüfek, yakıcı mermiler veya roketler, ayrıca tam el bombası. Sürünme: Ctrl — yat / ayağa kalk (daha alçak, daha sessiz, daha isabetli ama yavaş).",
