"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Hemen oyna\" — menünün ilk düğmesi: portal göğünün altında kısa bir geçiş ve doğrudan savaş (herhangi bir tuş veya dokunuşla atla).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Vuruşlar vuruş gibi hissettirir: metalik ses ve kıvılcımlar, nişangâhta öldürme işareti (kafadan — sarı), ×N serisi, patlamalardan yumuşak sarsıntı, kilit öldürmelerde ağır çekim. Sarsıntı, ağır çekim ve ipucu Ayarlar'dan kapatılabilir.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Maç sonucu: süre, öldürmeler, en iyi seri, ★ MVP ve en iyi manga, maç kartı — \"⇪ Paylaş\", PNG veya oyuna bağlantı.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Kaynakların altında solda \"şimdi ne yapmalı\" ipucu: stratejist emri, ele geçirilecek nokta, Sürü saldırısı. ✕ veya F7 — küçült.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Sekmeyi kapatsan veya küçültsen de savaş kendiliğinden kaydedilir — menüde \"⟲ Devam\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5, yeni sürümü beğenmezsen diye \"🕘 Oyun sürümü\" menüsünde duruyor. Anonim istatistikler (isim veya e-posta yok) artık gönderiliyor; Ayarlar'dan kapatılabilir.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Hemen oyna\", vuruş geri bildirimi, paylaşım kartlı maç sonucu, \"ne yapmalı\" ipucu, otomatik kayıt",
"and older: v7.5, v7.4, milestones v1–v7.0":"ve eskiler: v7.5, v7.4, v1–v7.0 dönüm noktaları",
"New in v7.6":"v7.6'da yeni",
"NEW IN v7.6":"v7.6'DA YENİ",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Maç öncesi fraksiyon seçimi: \"Konsorsiyum\" (güç zırhlı ağır piyade, zırh ve topçu) veya \"Sürü\" (hız, dron sürüleri, bozulma etkili ağır atışlar). YZ diğerini oynar. Seçim hatırlanır.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Her fraksiyonun kendi araçları ve özelleri var: Konsorsiyum'un — \"Rhino\" tankı ve \"Seramit plakalar\", Sürü'nün — \"Dron sürüsü\" ve \"Faz jetpackleri\". Denge bot maçlarıyla test edildi.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Patlama kraterleri: topçu, roketler ve tank topları meteorda çukurlar açar — içlerinden yürüyüp geçebilir, araçla sürebilir ve içlerinde siper alabilirsin.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Askerler için üçüncü şahıs görünümü (V, hatırlanır; telefonda — Kontroller) ve merminin düşeceği yeri gösteren işaretli akıcı araç kamerası.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6, yenisini beğenmezsen diye \"🕘 Oyun sürümü\" menüsünde duruyor.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Maç öncesi seçimli Konsorsiyum / Sürü fraksiyonları, patlama kraterleri, üçüncü şahıs görünümü",
"and older: v7.6, v7.5, milestones v1–v7.0":"ve eskiler: v7.6, v7.5, v1–v7.0 kilometre taşları",
