"Anomaly ahead — it is crackling with current!":"Önde anomali var — elektrikle çatırdıyor!",
"Rods and lightning — a Crackler. It loves armour!":"Çubuklar ve şimşekler — bir Çatırtı. Zırhı çok sever!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomali! Zemin sıcaktan titriyor — Mangal!",
