"Anomaly — green mist! Acid, hold your breath!":"Anomali — yeşil sis! Asit, nefes almayın!",
"The mist is drifting our way, go around!":"Sis bize doğru sürünüyor, dolaşın!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomali! Hava cam gibi — Mercek, mermileri büküyor!",
