"Supply drop":"İkmal kutusu",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Güçlerinin yakınına kutu bırakır: mermi, el bombası, roket, silah parçaları, tamir kiti.",
"\"Grad\" rocket strike":"\"Grad\" roket saldırısı",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"3 saniye sonra geniş alana 16 roket — topçu ateşinden daha hızlı ve geniş.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Destek: kutu, keşif, \"Grad\", topçu ateşi (sonra 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"DİKKAT: Sürü'nün \"Grad\"ı bölgene geliyor!",
"Warning! Rocket salvo on our position!":"Dikkat! Mevzimize roket salvosu geliyor!",
"take the supply crate":"ikmal kutusunu al",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Meteordaki anomaliler (1. dalga): \"Şarkı Söyleyen Damar\" — uğuldayan ve yakındaki herkese ritmik darbelerle vuran parlak yeşil kristal; \"Girdap\" çeker ve fırlatır, \"Çatırtı\" çubuklar arasında ark yapar, \"Mangal\" ayağının altında alev alır, \"Asit sisi\" ve \"Mercek\" (mermileri ve görüntünü büker) etrafta sürüklenir.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalileri önceden hissedebilirsin (uğultu, parıltı, sıcak titreşimi). El bombası, roket veya cıvata (yanında E) ile boşalt: uykuya dalar, bazen artı ve eksi taşıyan bir artefakt bırakır. Takımın telsizden uyarır; düşmanlar (ve dostlar) bazen içlerine dalar — onları buraya çek!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Komuta puanıyla destek: savaşta 4 tane (telefonda 📡) — ikmal kutusu, keşif taraması, \"Grad\" roket saldırısı, nişangâha topçu ateşi. Stratejist anomalileri haritada ancak keşiften sonra görür.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Eski seferlerin harabelerinde, karargâhların yanında ve biten binaların yanında ikmal kutuları: mermi, el bombası, roket, silah parçaları (eklentileri açar).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7, \"🕘 Oyun sürümü\" menüsünde duruyor. Anomaliler Ayarlar'dan kapatılabilir.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomaliler (\"Şarkı Söyleyen Damar\" ve 5 tane daha), cıvata ve el bombasıyla boşaltma, artefaktlar, KP ile destek çağrıları, ikmal kutuları",
"and older: v7.7, v7.6, milestones v1–v7.0":"ve eskiler: v7.7, v7.6, v1–v7.0 kilometre taşları",
"New in v7.8":"v7.8'de yeni",
"NEW IN v7.8":"v7.8'DE YENİ",
"Close":"Kapat",
"Anomalies on the meteor":"Meteordaki anomaliler",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"Köşedeki ☰ duraklatma menüsünü açar: Devam, Yeniden başla, Eğitim, Grafikler, Ayarlar, Ana menü (onaylı). Telefon: sağ üstte ☰ (savaş eylemleri — \"⚡ Eylemler\" kutusu); PC: sağ üstte \"☰ Menü\" düğmesi veya Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafikler varsayılan olarak hep normaldir — Dendy yalnızca sen seçersen: \"Grafikler: Normal / Dendy (8-bit) / 16-bit\" anahtarı doğrudan ana menüde ve duraklatma menüsünde. Oyun çok takılırsa \"Dendy'yi aç\" düğmeli bir ipucu çıkar.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon ve tablet: sağdaki \"✋\" eylem düğmesi yalnızca yakında yapılacak bir şey varsa belirir — \"Al\" (zula, kutu), \"Bin\" (araç, taret, top), \"İnşa et\", \"İn\", anomalide \"Cıvata\". Vurgulanan nesneye dokunman da yeter.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strateji: parmağını ~0,3 sn basılı tut (telefon titrer, sarı halka çıkar) ve sürükle — seçim kutusu; normal kaydırma kamerayı oynatır. Sağda \"Kutu\" düğmesi de var; eğitimde \"Kutu\" adımı bir manga seçmeye dokunmayı da kabul eder.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: küçük düğmelere basmak kolaylaştı, 📡 destek listesi büyüdü, strateji panelleri artık duraklatma ve sonuç ekranlarının üstüne binmiyor. v7.8, \"🕘 Oyun sürümü\" menüsünde duruyor.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Telefonda ve PC'de ☰ menü, otomatik Dendy yok, dokunmatikte \"✋\" düğmesi, telefonda kutu seçimi",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Takılıyor mu? Dendy grafiklerini dene — daha hafif.",
