"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Parmağını yerde ~0,3 sn tut — telefon titrer ve sarı halka çıkar — sonra kaldırmadan sürükle: kutu oluşur. Ya da sağdaki \"Kutu\" düğmesini kullan. Bir mangaya dokunmak da işe yarar.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhone'da tam ekran için: \"Paylaş\" ⬆ → \"Ana Ekrana Ekle\" — oyun Safari çubukları olmadan açılır.",
"Open portal-meteor.pages.dev for that.":"Bunun için portal-meteor.pages.dev sitesini aç.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Dokun — seç · yere dokun — git · basılı tut — emir menüsü · basılı tut ve sürükle — kutu · 2 parmak — yakınlaştır",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Suikastçı kahraman: ışınlanan atılmalar, katana, shuriken. Düşman bölgelerinde kendi başına ışınlanır ve robotları doğrar. Taraf başına 1.",
"Shadow protocol":"\"Gölge\" protokolü",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Araştırma: Kışla'da robo-ninjayı açar. Bitmiş bir mekanik fabrikası gerekir.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Kahraman (taraf başına 1): düşman bölgelerinde kendi başına ışınlanır ve robotları doğrar; elle oynamak için ele geçir.",
"is ready. She works on her own (AUTO) — possess her to play manually":"Robo-ninja hazır. Kendi başına çalışır (OTO) — elle oynamak için ele geçir",
