"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ OTO: düşman bölgelerinde kendi başına zıplar ve doğrar. Joystick / WASD 1.5 sn duraklatır",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Elle: düşmana dokun — atıl ve vur, kaydır — savur, 🛡 — blokla",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Elle kontrol: sol tık — katana, sağ tık — blok, Shift — atılma, Q — shuriken, G — ışınlanma",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: düşmana dokun — atılıp vurur, sağdan kaydır — savurma, ● — vuruş, 🛡 — blok (zamanında = savuşturma), ⇑ — atılış, ✦ — shurikenler, ◎ — ışınlanma, OTO — kendi başına",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: sol tık — katana (basılı tut — ağır kesik), sağ tık — blok (zamanında = savuşturma), Shift/Z — atılış, Q — shurikenler, G — nişangâha ışınlan, havada zıpla — çift zıplama / duvarda koşu, {0} — OTO",
