"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor Radyo: EDMITRY'den 100'den fazla parça doğrudan oyunda — 📻 düğmesi (PC: 5 tuşu, [ ] — parça). Müzik gerektiğinde akıtılır, oyunu şişirmez; ses ve otomatik başlatma Ayarlar'da, ayrıca \"Spotify'da dinle\" bağlantısı var.",
