"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 sağda — Portal Meteor Radyo: savaşırken EDMITRY müziği.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor Radyo: savaşırken EDMITRY müziği. [ ] — parça.",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor Radyo (EDMITRY): ses",
"Radio: start by itself in battle":"Radyo: savaşta kendiliğinden başlasın",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: katanalı bir siborg. Kışla'da \"Gölge Protokolü\" araştırmasıyla açılır (mekanik fabrikası gerekir). Kendi kendine düşman bölgelerine ışınlanır, düşmanları parçalara böler (kan yok — kıvılcım), atılır, shuriken fırlatır, düşman ninjasıyla düello yapar. Onu Ele Geçir — OTO modu ya da elle kontrol (telefonda kendi düğmeleri var).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor Radyo: EDMITRY'nin 103 parçası doğrudan oyunda. 5 tuşu (yeniden atanabilir), telefonda — ☰ → Ayarlar → Ses. Ses ve \"savaşta kendiliğinden başlasın\" ayarlardadır; müzik patlamalarda ve telsiz sesinde kısılır.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Yeni diller: Özbekçe ve Tacikçe — tam; Çince, İspanyolca, Portekizce — kısmi. Menüde \"Yeni maç\" yanında yeni dil seçici.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: \"simgeleri gizle\" 👁 kalan düğmeleri sağ kenarda derli toplu bir sütunda toplar; dikey modda artık çakışma yok; iPhone — oyun artık Safari hareketleriyle çatışmıyor, \"Paylaş → Ana Ekrana Ekle\" ile tam ekran açılıyor.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1'den: köşede ☰ menüsü (duraklat, yeniden başlat, eğitim, grafikler), otomatik Dendy yok, telefonda ✋ eylem düğmesi. v7.8.1 ve v7.8 \"🕘 Oyun sürümü\" menüsünde duruyor.",
