"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"\"Tabya\" ve \"Orakçı\": 12:00'den itibaren (burada atlanır), fabrika, montaj, emirler, zayıf noktalar, kontrol alma",
