"The bomber took off from the base — into the sky, it will come out over the target":"Bombardıman uçağı üsten havalandı — gökyüzüne çıktı, hedefin üstünde belirecek",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Bir birim seç → \"▶ Ele Geçir\" ya da çift dokun. Sağ üstteki mod düğmesi: Stratejist → Komutan → Nişancı.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Bir birim seç → \"▶ Ele Geçir\" ya da çift tık. {0} döngüde: Stratejist → Komutan → Nişancı.",
