"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Birliklerin yardım ister ve seni ödüllendirir, kahramanlar görev verir, tıkanan cepheyi bir operasyon kırar",
"A request":"Bir istek",
"Breakthrough":"Dönüm noktası",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Birliklerin ara sıra yardım ister: telsiz çağrısı, bir İSTEK kartı ve ✋ işareti. Bir müfreze sıkıştı — yanındaki düşmanları yok et. Ödül: üsten kapsülle bir asker, bir arabanın bagajından silah, nişancı koltuğu ya da yörünge desteği. İstemezsen — ✕ ya da yok say.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Gazi keşif eri \"Baykuş\" bir görev öneriyor. Y — kabul (N — ret). ★ işaretine git, nöbetçileri temizle ve pilotun yanında 3 sn dur — müfrezene katılır.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Cephe tıkandı — Karargâh bir atılım öneriyor. Y — kabul. Röleyi yakında düşman olmadan 8 sn elinde tut: düşman haritası 60 sn açılır. Jeneratör — düşman taretleri 2 dk susar. Stratejist'te — \"Müfreze ata\". Düşman da bunu yapabilir: ⚠ işaretine dikkat.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Birliklerin yardım ister: bir İSTEK kartı ve ✋ işareti. Sıkışan müfrezenin yanındaki düşmanları yok et — ödül al. ✕ — geç.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Kahraman \"Baykuş\" bir görev öneriyor — \"Kabul et\"e dokun. ★'a git, nöbetçileri temizle, pilotun yanında dur.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Cephe tıkandı — \"Kabul et\"e dokun ve röleyi 8 sn elinde tut: düşman haritası bir dakika açılır.",
