"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Zayıf nokta — karnın altındaki parlayan çekirdek: alttan hasar ×{0}. Bozulma ışını ve alan ezmesi; bariyerlerin üstünden geçer — mesafeni koru, öbek olma.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Karşı: hava bombaları ve topçu (×{0}), roketler (×{1}), halı bombardımanı; mermiler neredeyse çizmez (×{2}).",
