"Discharge: an explosion or a thrown bolt (E / \"Bolt\") — it sleeps 20–35 s, sometimes leaves an artifact.":"Etkisizleştir: patlama ya da atılan cıvata (E / \"Cıvata\") — 20–35 sn uyur, bazen artefakt bırakır.",
