"Plant race":"Bitki ırkı",
"Live in the Green anomalous zone, drawn to crystal veins. Neutral until touched or approached; dangerous to both sides. Fire and napalm ×1.6.":"Yeşil anomali bölgesinde yaşar, kristal damarlara yönelir. Dokunulmadıkça ya da yaklaşılmadıkça tarafsızdır; iki tarafa da tehlikelidir. Ateş ve napalm ×1.6.",
"Biome":"Biyom",
"Weather":"Hava durumu",
"A humming green crystal that pulses around itself — it flashes before each pulse.":"Vızıldayan yeşil bir kristal, çevresine ritmik darbeler yayar — her darbeden önce parlar.",
"Pulls you to the centre and slams you down. Look for rocks floating above it.":"Seni merkeze çeker ve yere çarpar. Çukurun üstünde asılı duran kayalardan anlaşılır.",
"Electric arcs between rods hit everyone inside, vehicles too.":"Çubuklar arasındaki elektrik arkları içerideki herkesi vurur, araçları da.",
"Step on it and a pillar of fire bursts out. The air shimmers above it.":"Basarsan bir ateş sütunu fışkırır. Üstünde sıcak hava titrer.",
"A drifting green cloud: damage over time while inside.":"Sürüklenen yeşil bir bulut: içinde durdukça zamanla hasar verir.",
"A drifting space distortion: bends bullets and warps the screen.":"Sürüklenen bir uzay bozulması: mermileri büker, ekranı dalgalandırır.",
"Dust falls upwards: a unit is pulled into the sky portal and thrown out at the antipode ~5 s later (exit visible to both sides).":"Toz \"yukarı düşer\": bir birim gök portalına çekilir ve ~5 sn sonra karşı kutupta dışarı atılır (çıkış iki tarafça da görülür).",
"A 10×10 m square of big \"pixels\": jerky movement, +50% spread, AI loses targets.":"10×10 m'lik iri \"piksel\" karesi: hareket sarsıntılı, saçılma +%50, YZ hedefleri kaybeder.",
"Frost on the ground, 2 s of hissing — then a steam column: freeze (−60% speed, +40% blast damage, 8 s). Snow.":"Yerde kırağı, 2 sn tıslama — sonra buhar sütunu: donma (hız −%60, patlama hasarı +%40, 8 sn). Kar.",
"A 6×30 m strip of haze pushes units, jetpacks and even projectiles; direction changes every 2 minutes. Autumn.":"6×30 m'lik bir sıcak hava şeridi birimleri, jetpack'leri, hatta mermileri iter; yön 2 dakikada bir değişir. Sonbahar.",
"Grey static: no radio or support inside, robot vision ×0.4, shots are quiet.":"Gri statik: içeride telsiz ve destek yok, robot görüşü ×0.4, atışlar sessiz.",
"A meadow of steel dandelions: fluff sticks and corrodes armour −2/s, jumps to neighbours on contact.":"Çelik karahindiba çayırı: tüy yapışır ve zırhı saniyede −2 aşındırır, temasla komşulara sıçrar.",
"A rootstock with vines: barely moves, lashes everyone nearby (damage and knockback).":"Sarmaşıklı bir kök gövdesi: neredeyse hiç yürümez, yakındaki herkesi sarmaşıkla kamçılar (hasar ve savurma).",
"Hit it from range — beyond its aggro radius it is harmless.":"Uzaktan vur — saldırganlık yarıçapının ötesinde zararsızdır.",
"A mushroom with a glowing cap: touch or approach it and it bursts into spores (damage and suppression, 6 s).":"Parlayan şapkalı bir mantar: dokunur ya da yaklaşırsan spor bulutuna dönüşür (hasar ve baskı, 6 sn).",
"Shoot from afar or walk around.":"Uzaktan ateş et ya da etrafından dolan.",
"Armoured and slow, bullets barely work; anger it and it rams.":"Zırhlı ve yavaş, mermiler neredeyse işlemez; kızdırırsan çarpar.",
"Rockets, grenades, fire.":"Roketler, el bombaları, ateş.",
"A three-legged hunter: get close and it chases you and claws, gives up after 20 s.":"Üç bacaklı bir avcı: yaklaşırsan seni kovalar ve pençeler, 20 sn sonra vazgeçer.",
"Keep your distance or escape by jetpack.":"Mesafeni koru ya da jetpack'le kaç.",
"A rootstock on root legs: burrows (a dust mound moves underground, invulnerable), surfaces under its target and tosses it.":"Kök bacaklı bir kök gövdesi: yeraltına gömülür (toz yığını yerin altında ilerler, dokunulmazdır), hedefin altında çıkıp onu havaya fırlatır.",
"Watch the mound and back off; hit it while it is above ground.":"Toz yığınını izle ve geri çekil; yerin üstündeyken vur.",
"A cloud of glowing worms: chases you and nibbles; bullets barely work.":"Parlayan solucanlardan bir bulut: seni kovalar ve azar azar ısırır; mermiler neredeyse işe yaramaz.",
"An explosion scatters it for 6 s — a grenade beats the MG.":"Patlama sürüyü 6 sn dağıtır — el bombası makineliden iyidir.",
"Dust and basalt, caps around the HQs, lava. Standard combat rules.":"Toz ve bazalt, karargâhların çevresinde başlıklar, lav. Olağan savaş kuralları.",
"Emerald grass, spores, crystals: the grass hides infantry beyond 40 m until it fires. Verdans live here.":"Zümrüt çimen, sporlar, kristaller: çimen piyadeyi gizler — ateş etmediği sürece 40 m ötesinde görünmez. Verdanlar burada yaşar.",
"Autumn leaves: footsteps are louder — the enemy hears runners at 32 m. Draughts and Steel fluff appear here.":"Sonbahar yaprakları: ayak sesleri daha gür — düşman koşanları 32 m'den duyar. Burada Cereyanlar ve Çelik Tüyü görülür.",
"Snow: infantry −15% speed, vision ×0.7, an ice lake nearby; blizzards and coolant geysers.":"Kar: piyade hızı −%15, görüş ×0.7, yakında buz gölü; tipi ve soğutucu gayzerler.",
"Visibility ×0.65, footsteps are silent.":"Görüş ×0.65, ayak sesleri duyulmaz.",
"Visibility 25 m: the AI cannot target beyond it.":"Görüş 25 m: YZ bunun ötesinde hedef alamaz.",
"From big explosions, wrecks and napalm (30 s): targets in smoke beyond 10 m are hidden.":"Büyük patlamalardan, enkazlardan ve napalmdan (30 sn): dumandaki hedef 10 m ötesinde görünmez.",
"White cap only: visibility ×0.5, a white veil.":"Yalnızca \"Beyaz başlık\"ta: görüş ×0.5, beyaz perde.",
"Dust storm and meteor shower":"Toz fırtınası ve meteor yağmuru",
